def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract opponent and own action sequences
    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = op.count('C')
    opp_d = n - opp_c
    my_c = my.count('C')
    my_d = n - my_c

    last_my = my[-1]
    last_op = op[-1]
    rounds_left = 100 - n

    # Opening: cooperate to establish mutual cooperation
    if n <= 2:
        return 'C'

    # ---------------- Endgame exploitation ----------------
    # Near the very end, exploit opponents who have shown they keep
    # cooperating even after we've defected on them.
    if rounds_left <= 3:
        # Count how often the opponent retaliated to our defections
        opp_retaliations = 0
        opp_opportunities = 0
        for i in range(1, n):
            if my[i - 1] == 'D':
                opp_opportunities += 1
                if op[i] == 'D':
                    opp_retaliations += 1
        forgiving = (opp_opportunities == 0) or (opp_retaliations * 2 < opp_opportunities)

        # If opponent is very cooperative overall, exploit at the end
        if opp_d <= n // 5 and forgiving:
            return 'D'
        # If opponent is clearly exploitative, defect
        if opp_d > opp_c:
            return 'D'
        # Otherwise, safe cooperate
        return 'C'

    # ---------------- Opponent classification ----------------
    recent_len = 8 if n >= 8 else n
    recent_op = op[-recent_len:]
    recent_c = recent_op.count('C')
    recent_d = recent_len - recent_c

    # Near-total defector: punish hard
    if recent_d >= recent_len - 1 and n >= 5:
        # Occasional probe to check if they might cooperate back
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Opponent almost never defects: cooperate, with very rare probing
    if opp_d <= max(1, n // 12) and n >= 6:
        # Rare probes only before endgame, and only if we have not probed recently
        if rounds_left > 10 and last_my == 'C':
            recent_my_d = my[-8:].count('D') if n >= 8 else my_d
            if recent_my_d == 0 and rng.random() < 0.03:
                return 'D'
        return 'C'

    # Opponent very defection-heavy overall
    if opp_d > n * 0.7:
        return 'D'

    # ---------------- Cooperation-streak detection ----------------
    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            coop_streak += 1
        else:
            break

    def_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            def_streak += 1
        else:
            break

    # If opponent is on a strong cooperative streak, cooperate to keep it going
    if coop_streak >= 3:
        return 'C'

    # If opponent is on a long defection streak, retaliate but signal willingness
    if def_streak >= 3:
        # Occasionally offer a peace signal to break DD cycles
        if def_streak >= 4 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # ---------------- Alternator detection ----------------
    # Detect strict alternating CD patterns which try to exploit TFT
    if n >= 6:
        tail = op[-6:]
        if tail == ['C', 'D', 'C', 'D', 'C', 'D'] or tail == ['D', 'C', 'D', 'C', 'D', 'C']:
            return 'D'
    if n >= 4:
        tail4 = op[-4:]
        if tail4 == ['C', 'D', 'C', 'D']:
            # Predict C next, defect
            return 'D'
        if tail4 == ['D', 'C', 'D', 'C']:
            # Predict D next, defect too
            return 'D'

    # ---------------- Main policy: generous tit-for-tat ----------------
    if last_op == 'C':
        # Opponent cooperated: cooperate back, but avoid being exploited
        # If our last was D and opponent responded C, they are forgiving;
        # do not exploit too obviously mid-game.
        if last_my == 'D':
            return 'C'
        return 'C'

    # Opponent defected last round
    if last_my == 'C':
        # They defected on our cooperation: retaliate, but allow rare forgiveness
        # if opponent has otherwise been fairly cooperative
        if opp_c >= n * 0.6 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # last_my == 'D' and last_op == 'D': stuck in DD
    # Count recent mutual cooperation to decide whether to try resetting
    recent_mutual_c = 0
    for i in range(max(0, n - 6), n):
        if my[i] == 'C' and op[i] == 'C':
            recent_mutual_c += 1

    if opp_c >= n * 0.4 and recent_mutual_c >= 1:
        # History of some cooperation: try to reset
        if rng.random() < 0.45:
            return 'C'
        return 'D'

    if opp_c >= n * 0.25 and rng.random() < 0.2:
        return 'C'

    return 'D'
